args.command:
cd /tmp/probe/order && cat > onlynamed.go <<'EOF'
package main

import (
	fmtalias "fmt"
	named "github.com/named/pkg"
)

func main() {}
EOF
echo "=== group with ONLY named imports, separate-named ===" && /workspace/executable -separate-named -output stdout onlynamed.go 2>/dev/null; echo "EXIT:$?"
cat > samealias.go <<'EOF'
package main

import (
	os "os"
	"fmt"
)

func main() {}
EOF
echo; echo "=== alias same as pkg name, separate-named ===" && /workspace/executable -separate-named -output stdout samealias.go 2>/dev/null; echo "EXIT:$?"
echo; echo "=== separate-named + custom order project,std,general,company ===" && /workspace/executable -company-prefixes github.com/mycompany -separate-named -imports-order project,std,general,company -output stdout named.go 2>/dev/null; echo "EXIT:$?"
